  name: userName,              // zmiana nazwy: name -> userName
  age: userAge = 30,           // wartosc domyslna: age nie istnieje -> 30
  address: { city }            // zagniezdzenie: wyciagniecie city z address
} = user;

console.log(userName); // "Anna"
console.log(userAge);  // 30
console.log(city);     // "Krakow"

