const { adres: { miasto } } = firma;
console.log(miasto); // "Poznan"

const ksiazka = { tytul: "Diuna", autor: "Frank Herbert", rok: 1965 };
const { tytul, ...rest } = ksiazka;
console.log(rest); // { autor: 'Frank Herbert', rok: 1965 }

function opiszKsiazke({ tytul, autor }) {
  return `${tytul} - ${autor}`;
}

const ksiazka = { tytul: "Diuna", autor: "Frank Herbert" };
console.log(opiszKsiazke(ksiazka)); // "Diuna - Frank Herbert"

function pokazMiasto({ adres: { miasto } = {} }) {
  return miasto;
}

console.log(pokazMiasto({ nazwa: "Firma" })); // undefined - bez bledu

const ustawienia = { motyw: "ciemny", jezyk: "pl", powiadomienia: true, dzwiek: false };
const { motyw, jezyk } = ustawienia;
console.log(motyw, jezyk); // "ciemny" "pl"

const osoba = { imie: "Jan", wiek: 30 };
const { imie: name, wiek: age } = osoba;
console.log(name, age); // "Jan" 30

const konfiguracja = { port: 8080 };
const { host = "localhost", port } = konfiguracja;
console.log(host, port); // "localhost" 8080

const uzytkownik = { imie: "Ala", ustawienia: { motyw: "ciemny" } };
const { imie, ustawienia: { motyw } } = uzytkownik;
console.log(imie, motyw); // "Ala" "ciemny"

const firma = { nazwa: "Techno", adres: { miasto: "Poznan", kod: { pocztowy: "60-001" } } };
const { adres: { kod: { pocztowy } } } = firma;
console.log(pocztowy); // "60-001"

function obliczCene({ cena, ilosc = 1 }) {
  return cena * ilosc;
}

console.log(obliczCene({ cena: 50 }));            // 50
console.log(obliczCene({ cena: 50, ilosc: 3 }));  // 150

function stworzKarte({ imie, dzial, ...pozostaleDane }) {
  return { podglad: `${imie} (${dzial})`, szczegoly: pozostaleDane };
}

console.log(stworzKarte({ imie: "Jan", dzial: "IT", wiek: 30, email: "jan@test.pl" }));
// { podglad: 'Jan (IT)', szczegoly: { wiek: 30, email: 'jan@test.pl' } }

const produkty = [{ nazwa: "A", cena: 10 }, { nazwa: "B", cena: 20 }];
const nazwy = produkty.map(({ nazwa }) => nazwa);
console.log(nazwy); // ['A', 'B']

const produkty = [{ nazwa: "A", dostepny: true }, { nazwa: "B", dostepny: false }];
const dostepne = produkty.filter(({ dostepny }) => dostepny);
console.log(dostepne); // [{ nazwa: 'A', dostepny: true }]

const obiekt = { a: 1, b: 2, c: 3, d: 4 };
const { a, b, ...rest } = obiekt;
console.log(Object.keys(rest)); // ['c', 'd']

function przywitaj({ imie = "Gosciu" } = {}) {
  return `Witaj, ${imie}!`;
}

console.log(przywitaj());              // "Witaj, Gosciu!"
console.log(przywitaj({}));            // "Witaj, Gosciu!"
console.log(przywitaj({ imie: "Jan" })); // "Witaj, Jan!"

const odpowiedzApi = { status: 200, dane: { uzytkownicy: ["Jan", "Ala"] }, blad: null };
const { status, dane: { uzytkownicy } } = odpowiedzApi;
console.log(status, uzytkownicy); // 200 ['Jan', 'Ala']

function formatujAdres({ ulica, miasto, kodPocztowy: kod = "brak" }) {
  return `${ulica}, ${kod} ${miasto}`;
}

console.log(formatujAdres({ ulica: "Dluga 5", miasto: "Krakow" }));
// "Dluga 5, brak Krakow"

const elementy = [{ id: 1, nazwa: "A" }, { id: 2, nazwa: "B" }];
for (const { id, nazwa } of elementy) {
  console.log(id, nazwa);
}
// 1 "A"
// 2 "B"

function wyswietlProdukt({ nazwa, cena, waluta = "PLN" } = { nazwa: "Nieznany", cena: 0 }) {
  return `${nazwa}: ${cena} ${waluta}`;
}

console.log(wyswietlProdukt()); // "Nieznany: 0 PLN"

const punkt = { x: 5, y: 10 };
const { x, y } = punkt;
const suma = x + y;
console.log(suma); // 15

const transakcje = [{ kwota: 100 }, { kwota: -30 }, { kwota: 50 }];
const suma = transakcje.reduce((s, { kwota }) => s + kwota, 0);
console.log(suma); // 120

function logujBlad({ kod, wiadomosc = "Nieznany blad", szczegoly: { linia } = {} }) {
  return `Blad ${kod}: ${wiadomosc} (linia: ${linia})`;
}

console.log(logujBlad({ kod: 404 })); // "Blad 404: Nieznany blad (linia: undefined)"

const obiekt = { dane: [1, 2, 3] };
const { dane } = obiekt;
const [pierwszy] = dane;
console.log(pierwszy); // 1

const obiekt = { dane: [1, 2, 3] };
const { dane: [pierwszy] } = obiekt;
console.log(pierwszy); // 1

function sprawdzUprawnienia({ rola, uprawnienia = [] }) {
  return uprawnienia.includes("admin");
}

console.log(sprawdzUprawnienia({ rola: "user" })); // false
console.log(sprawdzUprawnienia({ rola: "admin", uprawnienia: ["admin", "edit"] })); // true

const wynikTestu = { pytanie1: true, pytanie2: false, pytanie3: true };
const { pytanie1, pytanie2, pytanie3 } = wynikTestu;
const poprawne = pytanie1 + pytanie2 + pytanie3;
console.log(poprawne); // 2

function stworzKontakt({ imie, telefon = "brak", email = "brak" }) {
  return { imie, telefon, email };
}

console.log(stworzKontakt({ imie: "Jan", email: "jan@test.pl" }));
// { imie: 'Jan', telefon: 'brak', email: 'jan@test.pl' }

